var ENT=[["Logstash", "Elastic's log ingestion pipeline."], ["Fluentd", "Unified logging layer in CNCF."], ["Airbyte", "Open-source data integration connectors."], ["RSS feeds", "Syndication formats for update ingestion."], ["Apache Kafka", "Distributed event-streaming platform; the standard backbone for real-time ingestion."], ["Scrapy", "A Python web-crawling framework with spiders, pipelines and politeness controls."], ["Beautiful Soup", "A forgiving Python HTML and XML parser beloved for quick scraping jobs."]];
